import {openBrowser} from 'vitexec/cli';
const b=await openBrowser({gpu:true});try{const c=await b.newContext({ignoreHTTPSErrors:true,viewport:{width:1440,height:960}});const p=await c.newPage();p.on('pageerror',e=>console.log('PAGEERROR',e.message));p.on('console',m=>{if(m.type()==='error')console.log('CONSOLE',m.text());});await p.goto('https://async-transition-stress.localhost:1355/native-three-host.html',{waitUntil:'networkidle'});await p.waitForFunction(()=>window.__nativeThreeDiagnostics?.snapshot().rendererFrames>10,{timeout:15000});console.log(JSON.stringify(await p.evaluate(()=>window.__nativeThreeDiagnostics.snapshot())));await p.screenshot({path:'.cache/three-scene-initial.png'});await p.evaluate(()=>window.dispatchEvent(new Event('pagehide')));}finally{await b.close();}
